const COLOR = {
  icon: IconColor,
  wordmark: WordmarkColor,
  horizontal: HorizontalColor,
  stacked: StackedColor,
};

const MONO = {
  icon: IconMono,
  wordmark: WordmarkMono,
  horizontal: HorizontalMono,
  stacked: StackedMono,
};

export type AeruneLogoProps = Omit<SVGProps<SVGSVGElement>, "type" | "style"> & {
  variant?: "color" | "mono";
  type?: "icon" | "wordmark" | "horizontal" | "stacked";
  mode?: "auto" | "light" | "dark";
  title?: string;
  style?: AeruneLogoStyle;
};

export function AeruneLogo({
  variant = "color",
  type = "horizontal",
  mode = "auto",
  title,
  height,
  width,
  style,
  className,
  ...props
}: AeruneLogoProps) {
  const systemDark = useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
  const dark = mode === "dark" || (mode === "auto" && systemDark);
  const palette = dark ? DARK : LIGHT;
  const content = variant === "mono" ? MONO[type] : COLOR[type];
  const box = BOX[type];
  const ratio = box.w / box.h;
  const decorative = !title;
  const theme: AeruneLogoStyle | undefined =
    variant === "mono"
      ? undefined
      : {
          "--ld-bg": palette.bg,
          "--ld-ink": palette.ink,
          "--ld-brand": palette.brand,
          "--ld-accent": palette.accent,
        };

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={`${box.x} ${box.y} ${box.w} ${box.h}`}
      role={decorative ? "presentation" : "img"}
      aria-hidden={decorative ? true : undefined}
      aria-label={decorative ? undefined : title}
      height={height ?? "1em"}
      width={width ?? `${Math.round(ratio * 1000) / 1000}em`}
      preserveAspectRatio="xMidYMid meet"
      className={className}
      style={{ ...theme, ...style }}
      {...props}
    >
      {title ? <title>{title}</title> : null}
      {content}
    </svg>
  );
}

export default AeruneLogo;
